use crate::*;
use serde::{Deserialize,Serialize};
use super::{plan::{PackPlan,Resource,Loader},policy,state,snapshot};
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct Target{pub minecraft:String,pub loader:String,pub loader_version:String}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct Mapping{pub source:String,pub name:String,pub old_project_id:String,pub old_version_id:String,pub new_project_id:String,pub new_version_id:String,pub action:String,pub reason:String}
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct MigrationPlan{pub source_instance_id:String,pub target:Target,pub mappings:Vec<Mapping>,pub unresolved:Vec<String>,pub config_warnings:Vec<String>,pub estimated_download_bytes:u64}
impl MigrationPlan{pub fn check(&self)->Result<()>{safe_name(&self.source_instance_id)?;safe_name(&self.target.minecraft)?;if self.mappings.len()>80||self.estimated_download_bytes>policy::MAX_BYTES{return Err("迁移计划超过 80 模组或 2 GB 预算".into());}for row in &self.mappings{if !["modrinth","curseforge"].contains(&row.source.as_str())||!["keep","replace","drop","unresolved"].contains(&row.action.as_str()){return Err("迁移映射类型无效".into());}if ["keep","replace"].contains(&row.action.as_str()){safe_name(&row.new_project_id)?;safe_name(&row.new_version_id)?;}}Ok(())}pub fn hash(&self)->Result<String>{Ok(super::update::digest(&serde_json::to_value(self).map_err(err)?))}}
pub async fn plan(core:&Core,id:&str,args:&Value)->Result<Value>{let cfg=read_json(&core.instance(id)?.join("kxl.json"))?;let mut target:Target=serde_json::from_value(args["target"].clone()).map_err(|_|"请填写目标游戏、加载器及加载器版本")?;let base=metadata::version(core,&target.minecraft).await?;if base["id"]!=target.minecraft{return Err("目标游戏版本不存在".into());}if target.loader!="vanilla"{let rows=loader_catalog::loaders(core,&target.minecraft,&target.loader,false).await?;if target.loader_version.is_empty(){target.loader_version=rows.as_array().and_then(|a|a.first()).and_then(Value::as_str).ok_or("此游戏没有兼容加载器")?.into();}if !rows.as_array().is_some_and(|a|a.iter().any(|v|v==&target.loader_version)){return Err("目标加载器版本不兼容".into());}}
 let identities=super::update::identities(core,id)?;if identities.len()>80{return Err("当前实例超过 80 个已识别模组，请先缩小迁移范围".into());}let mut mappings=Vec::new();let mut unresolved=Vec::new();let mut bytes=0;
 for item in identities{core.stopped()?;let source=string(&item,"source")?;let project=string(&item,"projectId")?;let selected=if source=="modrinth"{engine::project_version(core,project,&target.minecraft,&target.loader,"mods").await.map(|v|(v["project_id"].as_str().unwrap_or(project).to_owned(),v["id"].as_str().unwrap_or("").to_owned(),v["files"][0]["size"].as_u64().unwrap_or(0)))}else{let key=curseforge::configured_key(core,"");curseforge::best_file(core,project.parse().map_err(|_|"项目 ID 无效")?,Some(&target.minecraft),Some(&target.loader),key.as_deref()).await.map(|v|(project.into(),v["id"].as_u64().unwrap_or(0).to_string(),v["fileLength"].as_u64().unwrap_or(0)))};
 let name=string(&item,"name")?.to_owned();let old=string(&item,"versionId")?.to_owned();let (new_project,new_version,action,reason)=match selected{Ok((p,v,n))=>{bytes+=n;let action=if p==project&&v==old{"keep"}else{"replace"};(p,v,action,"通过真实目录找到目标版本".to_owned())},Err(_)=>{unresolved.push(name.clone());(String::new(),String::new(),"unresolved","没有找到兼容版本，迁移前须明确确认移除；不会修改原实例".to_owned())}};mappings.push(Mapping{source:source.into(),name,old_project_id:project.into(),old_version_id:old,new_project_id:new_project,new_version_id:new_version,action:action.into(),reason});
 }
 let known=mappings.iter().map(|v|v.name.clone()).collect::<std::collections::HashSet<_>>();let root=core.instance(id)?;for entry in std::fs::read_dir(root.join("mods")).into_iter().flatten().flatten(){let name=entry.file_name().to_string_lossy().into_owned();if name.ends_with(".jar")&&!known.contains(&name){unresolved.push(format!("{name}（未识别来源的本地文件，不自动迁移）"));}}
 let result=MigrationPlan{source_instance_id:id.into(),target,mappings,unresolved,config_warnings:vec!["仅复制 UTF-8 的安全 JSON/TOML/properties/CFG；旧配置不保证适配新版本。".into(),"存档默认不复制。勾选复制时会先单独备份；跨版本打开世界存在不可逆转换风险。".into()],estimated_download_bytes:bytes};result.check()?;Ok(json!({"migrationHash":result.hash()?,"plan":result,"sourceName":cfg["name"]}))}
pub(super) fn copy_tree(source:&Path,target:&Path,relative:&str,max_bytes:u64)->Result<()> {fn walk(source:&Path,target:&Path,path:&str,count:&mut usize,total:&mut u64,max:u64)->Result<()>{let from=policy::under(source,path)?;if !from.exists(){return Ok(());}if from.is_dir(){for e in std::fs::read_dir(from).map_err(err)?{let e=e.map_err(err)?;let name=e.file_name().into_string().map_err(|_|"文件名无效")?;walk(source,target,&format!("{path}/{name}"),count,total,max)?;}}else{*count+=1;*total+=std::fs::metadata(&from).map_err(err)?.len();if *count>20000||*total>max{return Err("复制文件超过数量或体积上限，请手动备份和迁移存档。".into());}let to=policy::under(target,path)?;std::fs::create_dir_all(to.parent().unwrap()).map_err(err)?;std::fs::copy(from,to).map_err(err)?;}Ok(())}let mut count=0;let mut total=0;walk(source,target,relative,&mut count,&mut total,max_bytes)}
fn copy_configs(source:&Path,target:&Path)->Result<Vec<String>>{let files=super::update::inventory(source)?;let mut skipped=Vec::new();for(path,_)in files{if !(path.starts_with("config/")||path.starts_with("defaultconfigs/")){continue;}let lower=path.to_lowercase();if ![".json",".toml",".properties",".cfg"].iter().any(|s|lower.ends_with(s))||["account","credential","token","password"].iter().any(|s|lower.contains(s)){skipped.push(path);continue;}let text=std::fs::read_to_string(policy::under(source,&path)?).map_err(|_|"某个配置不是 UTF-8，请手动迁移")?;if text.len()>2*1024*1024||ai_diagnose::agent_text(&text)!=text{skipped.push(path);continue;}if path.ends_with(".json")&&serde_json::from_str::<Value>(&text).is_err()||path.ends_with(".toml")&&toml::from_str::<toml::Value>(&text).is_err(){skipped.push(path);continue;}let to=policy::under(target,&path)?;std::fs::create_dir_all(to.parent().unwrap()).map_err(err)?;std::fs::write(to,text).map_err(err)?;}Ok(skipped)}
pub async fn apply(core:&Core,task:&mut state::Task,args:&Value,account:&str,settings:&Value)->Result<Value>{let migration:MigrationPlan=serde_json::from_value(args["plan"].clone()).map_err(|_|"迁移计划格式无效")?;migration.check()?;if migration.source_instance_id!=task.instance_id||migration.hash()?!=string(args,"migrationHash")?{return Err("迁移计划已改变，请重新预览并确认。".into());}if !migration.unresolved.is_empty()&&args["allowUnresolved"]!=true{return Err("存在未解决或需移除的模组，必须先明确确认这些项目不迁移。".into());}let original=read_json(&core.instance(&task.instance_id)?.join("kxl.json"))?;let mut p:PackPlan=task.plan.clone().ok_or("源实例缺少计划上下文")?;p.name=format!("{} - {}",original["name"].as_str().unwrap_or("迁移实例"),migration.target.minecraft);p.minecraft=migration.target.minecraft.clone();p.loader=Loader{kind:migration.target.loader.clone(),version:migration.target.loader_version.clone()};p.mods=migration.mappings.iter().filter(|r|["keep","replace"].contains(&r.action.as_str())).map(|r|Resource{source:r.source.clone(),project_id:r.new_project_id.clone(),version_id:r.new_version_id.clone(),name:r.name.clone(),side:"both".into(),reason:r.reason.clone(),required:true}).collect();p.resource_packs.clear();p.shaders.clear();p.config_patches.clear();p.estimated_download_bytes=0;p.notes=vec!["由已确认迁移计划生成的新实例，原实例保持不变。".into()];super::plan::validate(core,&mut p).await?;
 let mut next=task.clone();next.id=uuid::Uuid::new_v4().to_string();next.instance_id=uuid::Uuid::new_v4().to_string();next.mode="confirm".into();next.maintenance=false;next.status="executing".into();next.plan_hash=p.hash()?;next.confirmed_hash=next.plan_hash.clone();next.plan=Some(p);next.current_step=0;next.steps=super::executor::steps();next.snapshots.clear();next.rollback_snapshot.clear();next.results.clear();next.error.clear();next.audit.clear();next.created_at=policy::now().to_string();next.budget=json!({"maxMods":80,"maxDownloadBytes":policy::MAX_BYTES,"maxSteps":40,"spentMs":0,"downloadedBytes":core.agent_policy.as_ref().map(|p|p.bytes.load(Ordering::Relaxed)).unwrap_or(0)});
 state::runtime().lock().map_err(err)?.insert(next.id.clone(),core.cancel.clone());let _registration=super::Registration(next.id.clone());let child=super::child_core(core,&next.id);let target=child.instance(&next.instance_id)?;let sid=snapshot::create(&child,&next.instance_id)?;next.snapshots.push(sid.clone());next.rollback_snapshot=sid;state::save(&child,&mut next,"state")?;
 let result:Result<Value>=async{let source=core.instance(&task.instance_id)?;let mut skipped=Vec::new();if args["copyConfigs"]!=false{skipped=copy_configs(&source,&target)?;}if args["copySaves"]==true{let backup_id=uuid::Uuid::new_v4().to_string();let backup=policy::under(&core.data_root,&format!("world-backups/{}/{backup_id}",task.instance_id))?;std::fs::create_dir_all(&backup).map_err(err)?;copy_tree(&source,&backup,"saves",policy::MAX_BYTES)?;copy_tree(&backup,&target,"saves",policy::MAX_BYTES)?;next.results.insert("worldBackup".into(),json!({"backupId":backup_id,"note":"存档已单独备份；原实例未修改。"}));}super::executor::run(&child,&mut next,account,settings).await?;Ok(json!({"migrated":true,"newTaskId":next.id,"newInstanceId":next.instance_id,"sourceUnchanged":true,"skippedConfigs":skipped,"unresolved":migration.unresolved}))}.await;
 if let Err(e)=&result{next.status="failed".into();next.error=super::clean(e);state::save(&child,&mut next,"error")?;}result
}
#[cfg(test)]mod tests{use super::*;#[test]fn migration_hash_is_bound_to_target_and_ids(){let p=MigrationPlan{source_instance_id:"source".into(),target:Target{minecraft:"1.21.1".into(),loader:"fabric".into(),loader_version:"v".into()},mappings:vec![],unresolved:vec![],config_warnings:vec![],estimated_download_bytes:0};let hash=p.hash().unwrap();let mut changed=p.clone();changed.target.minecraft="1.20.1".into();assert_ne!(hash,changed.hash().unwrap());changed.estimated_download_bytes=policy::MAX_BYTES+1;assert!(changed.check().is_err());}#[test]fn copy_does_not_change_source(){let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();std::fs::create_dir(a.path().join("saves")).unwrap();std::fs::write(a.path().join("saves/world.dat"),b"original").unwrap();copy_tree(a.path(),b.path(),"saves",100).unwrap();std::fs::write(b.path().join("saves/world.dat"),b"new").unwrap();assert_eq!(std::fs::read(a.path().join("saves/world.dat")).unwrap(),b"original");}}
